import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.Ky-Ipuyb.js";const m=JSON.parse('{"title":"RmlUi source layout","description":"","frontmatter":{"lang":"en","sourcePath":"docs/rmlui/source-layout.md"},"headers":[],"relativePath":"rmlui/source-layout.md","filePath":"rmlui/source-layout.md"}'),r={name:"rmlui/source-layout.md"};function n(a,e,i,c,l,u){return d(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="rmlui-source-layout" tabindex="-1">RmlUi source layout <a class="header-anchor" href="#rmlui-source-layout" aria-label="Permalink to &quot;RmlUi source layout&quot;">​</a></h1><p><code>packages/sfml.js-rmlui</code> groups native bindings, TypeScript interfaces and tests by responsibility. Put new implementations in their owning module, with related headers and implementation files together.</p><table tabindex="0"><thead><tr><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>runtime/</code></td><td>Initialization, Context, runtime state, capabilities, callback lifetime, Plugin and Debugger</td></tr><tr><td><code>dom/documents/</code></td><td>Documents, Factory, attribute collections and XML parsing</td></tr><tr><td><code>dom/elements/</code></td><td>Element, layout, scrolling, element instancing, SVG and Lottie</td></tr><tr><td><code>dom/controls/</code></td><td>Forms, text controls, options and panels</td></tr><tr><td><code>data/</code></td><td>Data models, type registration, addresses, members, batching and diagnostics</td></tr><tr><td><code>events/</code></td><td>Events, listeners, dispatch and instancing</td></tr><tr><td><code>style/properties/</code></td><td>Property, parsers, specifications and stylesheets</td></tr><tr><td><code>style/effects/</code></td><td>Decorators, filters, effect values and their callbacks</td></tr><tr><td><code>style/values/</code></td><td>Computed styles, style structs, transforms and mapped views</td></tr><tr><td><code>animation/</code></td><td>Animations, transitions, tweens and value callbacks</td></tr><tr><td><code>rendering/</code></td><td>Render management, geometry, textures, layers, resources and the SFML renderer</td></tr><tr><td><code>fonts/</code></td><td>Font loading, FreeType/HarfBuzz/bitmap engines, measurement, glyphs and font effects</td></tr><tr><td><code>scripting/</code></td><td>Script interfaces, hosts and script objects</td></tr><tr><td><code>scripting/lua/</code></td><td>Lua hosts, models, values, functions and instancing</td></tr><tr><td><code>platform/</code></td><td>SFML system integration, input, text input and window density</td></tr><tr><td><code>io/</code></td><td>File interfaces and streams</td></tr><tr><td><code>values/</code></td><td>Variant, numeric values, strings, URLs and shared types</td></tr></tbody></table><p>These directories live under <code>native/</code> and <code>src/</code>. Implementations needed in only one layer stay there. <code>src/internal/</code> contains cross-module internal protocols such as native loading, wrapper allocation and shared-memory conversion.</p><p><code>src/index.ts</code> is the public npm entry point; <code>native/addon.cc</code> registers the native module. Package build configuration stays in the root <code>binding.gyp</code>, <code>package.json</code> and <code>tsconfig.json</code>.</p><p>Generated files live in <code>src/generated/</code> and <code>native/generated/</code>. Edit the generators in <code>tools/codegen/</code>, then regenerate their output.</p><table tabindex="0"><thead><tr><th>Tool directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>tools/build/</code></td><td>Package native builds, Lua C++ compilation and compilation-database repair; repository LSP databases merge only inside the owning Rush workspace</td></tr><tr><td><code>tools/codegen/</code></td><td>Input, event, property ID and style bindings generated from upstream headers</td></tr><tr><td><code>tools/dependencies/</code></td><td>Dependency versions, verification, downloads and build-source inventories</td></tr><tr><td><code>tools/dependencies/patches/</code></td><td>RmlUi, Lua, Debugger, numeric, string and rlottie patches</td></tr><tr><td><code>tools/performance/</code></td><td>Performance measurements and native call counts</td></tr><tr><td><code>tools/testing/</code></td><td>Recursive runtime test collection/execution, clipboard preservation, npm source-package inventories and build dependency verification</td></tr></tbody></table><p><code>test/</code> groups runtime and type cases by module. <code>test/native/</code> groups C++ oracle programs and their build scripts by module. These scripts reuse the package&#39;s existing object files; callers select an existing temporary output directory.</p><p><code>packages/sfmljs-rmlui-vscode/tools/testing/</code> runs extension integration checks in an existing VS Code installation. Its <code>tools/packaging/</code> verifies the VSIX&#39;s bundled client, language server, language resources and four-language README files. Repository Windows toolchain setup lives in <code>tools/ci/</code>, shared by the existing Node.js CI and the dedicated RmlUi CI.</p><p><code>third_party/</code> preserves upstream layouts. <code>build/</code> and <code>dist/</code> reuse existing build directories. After a source move, remove only old outputs that have corresponding outputs at the new paths.</p><p>Moving source directories does not establish full RmlUi 6.3 acceptance. Existing evidence under <code>audit/6.3/</code> retains the paths and hashes recorded when collected. Use the <a href="https://github.com/XadillaX/node-sfml/blob/main/docs/rmlui/audit/6.3/source-layout-map.json" target="_blank" rel="noreferrer">source relocation map</a> to find those historical paths.</p>',11)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
